-- Biology Ch11: The Musculoskeletal System — BATCH 4 (Skeletal System)
-- Safe to re-run: deletes only this batch's subtopics, then re-inserts.

DELETE FROM questions WHERE topic = 'The Musculoskeletal System' AND subtopic IN ('Bone Structure & Marrow', 'Bone Matrix & Microstructure', 'Bone Remodeling & Calcium Homeostasis', 'Cartilage & Ossification', 'Joints & Movement');

-- Q1 [Bone Structure & Marrow] easy skill1 ans=A
WITH q AS (
  INSERT INTO questions (section, topic, subtopic, question_text, options, correct_answer, explanation, difficulty, foundation, content_category, discipline, cognitive_skill, estimated_time_seconds)
  VALUES ('bio_biochem', 'The Musculoskeletal System', 'Bone Structure & Marrow', 'An anatomist sections a femur lengthwise and points to the tubular shaft running between the bone''s proximal and distal ends, noting that it encloses a hollow central cavity filled with yellow marrow. This region is best identified as the', '[{"label": "A", "text": "diaphysis."}, {"label": "B", "text": "epiphysis."}, {"label": "C", "text": "metaphysis."}, {"label": "D", "text": "periosteum."}]'::jsonb, 'A', 'This is a Biology question that falls under the content category ''Organ Systems.'' The answer is A because the diaphysis is the tubular shaft of a long bone whose hollow medullary cavity holds yellow marrow. In a long bone, the diaphysis is the shaft that runs between the proximal and distal ends, and the hollow region within it, the medullary cavity, is filled with yellow marrow, while its walls are built of dense compact bone (OpenStax A&P 2e, lines 9436–9438). The described region—a central tubular shaft enclosing a marrow-filled cavity—matches the diaphysis precisely. (Choice A) is correct: the diaphysis is the tubular shaft between the proximal and distal ends whose medullary cavity is filled with yellow marrow, exactly the structure the anatomist indicates. (Choice B) the epiphysis is the wider section at each end of the bone, filled with spongy bone whose spaces hold red marrow, not the central shaft holding yellow marrow (lines 9445–9446). (Choice C) the metaphysis is the narrow area where each epiphysis meets the diaphysis and contains the epiphyseal plate; it is a junctional region, not the tubular shaft enclosing the marrow cavity (lines 9446–9447). (Choice D) the periosteum is the fibrous membrane covering the outer surface of the bone, not an internal shaft region, and it has no medullary cavity (lines 9452–9453). This is a Knowledge of Scientific Concepts and Principles question because you must recall the definition and location of the diaphysis and distinguish it from neighboring bone regions.', 'easy', '3B', 'Organ Systems', 'biology', 1, 70)
  RETURNING id
)
