-- Q17 [Cartilage & Ossification] easy skill1 ans=C
WITH q AS (
  INSERT INTO questions (section, topic, subtopic, question_text, options, correct_answer, explanation, difficulty, foundation, content_category, discipline, cognitive_skill, estimated_time_seconds)
  VALUES ('bio_biochem', 'The Musculoskeletal System', 'Cartilage & Ossification', 'A histologist samples hyaline cartilage from the end of a long bone and observes a collagen-and-proteoglycan matrix that contains no blood vessels, with cells sitting in small spaces throughout it. Which cell type produces and resides within this matrix?', '[{"label": "A", "text": "Osteocytes"}, {"label": "B", "text": "Osteoblasts"}, {"label": "C", "text": "Chondrocytes"}, {"label": "D", "text": "Fibroblasts"}]'::jsonb, 'C', 'This is a Biology question that falls under the content category ''Organ Systems.'' The answer is C because chondrocytes are the cells of cartilage, secreting and residing within its avascular matrix. The matrix of cartilage consists of chondroitin-sulfate proteoglycans and collagen fibers, and embedded within this matrix are the chondrocytes, occupying spaces called lacunae; because cartilaginous tissue is avascular, all nutrients must diffuse through the matrix to reach these cells. This avascularity is precisely why the chondrocytes depend on diffusion and why cartilage heals slowly. (Choice A) Osteocytes are the cells of bone, not cartilage; the textbook describes them as bone cells located within lacunae in a mineralized, highly vascularized tissue, so they are not the cells that produce cartilage matrix. (Choice B) Osteoblasts are the bone cells responsible for forming new bone, synthesizing and secreting the collagen matrix and calcium salts of bone rather than the flexible chondroitin-sulfate matrix of cartilage. (Choice C) is correct: chondrocytes are the cartilage cells embedded in the avascular matrix, dependent on nutrient diffusion through that matrix. (Choice D) Fibroblasts are the most abundant cell type in connective tissue generally and secrete protein fibers and matrix into the extracellular space, but they are not the specialized cartilage-forming cell that resides in lacunae within the avascular cartilage matrix. This is a Knowledge of Scientific Concepts and Principles question because you must recall that chondrocytes are the cells that produce and inhabit the avascular matrix of cartilage.', 'easy', '3B', 'Organ Systems', 'biology', 1, 70)
  RETURNING id
)
